/* =====================================================================
 *  robot.c  -  Autocar line follower + Bluetooth manual control
 *
 *  Blue Pill (STM32F103C8) with HAL, project generated by STM32CubeMX.
 *  Settings: robot_config.h      Hardware handles come from main.c.
 *
 *  BIG PICTURE
 *    Robot_Loop() runs every LOOP_MS milliseconds:
 *      1. read the buttons            -> start/stop, change mode
 *      2. read the 4 line sensors     -> which ones see the line
 *      3. run the current mode        -> decide wheel speeds
 *      4. move the servo a small step -> smooth, never jerky
 *      5. update LEDs, print debug text
 * ===================================================================== */
#include "robot.h"
#include "robot_config.h"
#include <stdio.h>
#include <string.h>

extern TIM_HandleTypeDef htim2;   /* motor PWM: CH1 = A0, CH4 = A3 */
extern TIM_HandleTypeDef htim3;   /* servo PWM: CH4 = B1           */
extern UART_HandleTypeDef huart1; /* USB-serial cable (debug)      */
extern UART_HandleTypeDef huart3; /* Bluetooth module              */

/* ------------------------------------------------------------------ */
/*  Types and state                                                   */
/* ------------------------------------------------------------------ */
typedef enum { MODE_AUTO = 0, MODE_MANUAL, MODE_SENSOR_TEST, MODE_MOTOR_TEST, MODE_COUNT } Mode;

typedef enum {
    AS_IDLE = 0,      /* waiting for the START button              */
    AS_FOLLOW,        /* normal line following                     */
    AS_WIDE,          /* 3+ sensors on the line: junction or colour change */
    AS_CROSS,         /* driving straight across a junction        */
    AS_TURN,          /* turning onto a side branch                */
    AS_LOST,          /* line lost for too long: stopped           */
    AS_FINISHED       /* reached the end: stopped                  */
} AutoState;

static const char *MODE_NAME[MODE_COUNT] = { "AUTO", "MANUAL", "SENSOR", "MOTOR" };
static const char *STATE_NAME[] = { "IDLE", "FOLLOW", "WIDE", "CROSS", "TURN", "LOST", "FINISH" };

static const RouteAction route[] = ROUTE_LIST;
#define ROUTE_LEN ((int)(sizeof(route) / sizeof(route[0])))

typedef struct {
    GPIO_TypeDef *port; uint16_t pin;
    uint8_t  stable, last_raw;
    uint32_t changed_at, pressed_at;
    uint8_t  long_done;
    uint8_t  short_event, long_event;
} Button;

static Button btn_start = { BTN_START_PORT, BTN_START_PIN, 0, 0, 0, 0, 0, 0, 0 };
static Button btn_mode  = { BTN_MODE_PORT,  BTN_MODE_PIN,  0, 0, 0, 0, 0, 0, 0 };

static Mode      mode = MODE_AUTO;
static AutoState astate = AS_IDLE;

static uint8_t  black_bits;          /* bit i = sensor i sees BLACK            */
static uint8_t  line_bits;           /* bit i = sensor i sees the LINE colour  */
static uint8_t  inverted;            /* 1 = following a WHITE line on black    */
static int      error, last_error, last_side;
static uint32_t state_t0, lost_t0;
static uint8_t  was_lost;
static int      junction_index;
static uint8_t  finish_armed;
static int8_t   turn_dir;            /* -1 left, +1 right                      */
static uint8_t  turn_left_line;      /* turn phase: 0 = still on old line      */
static int      speed_l, speed_r;

/* servo */
static uint8_t  servo_on;
static int      servo_now = SERVO_OPEN_US, servo_target = SERVO_OPEN_US;
static uint32_t servo_t;

/* bluetooth */
static uint8_t  bt_byte;
static volatile uint8_t bt_buf[32];
static volatile uint8_t bt_head, bt_tail;
static uint32_t bt_last;
static int      manual_speed = MANUAL_SPEED_DEFAULT;

/* motor test */
static uint8_t  mt_running;
static uint32_t mt_t0;

static uint32_t loop_t, print_t;

/* ------------------------------------------------------------------ */
/*  Small helpers                                                     */
/* ------------------------------------------------------------------ */
static int clamp(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }

static void debug_print(const char *s)
{
    HAL_UART_Transmit(&huart1, (uint8_t *)s, (uint16_t)strlen(s), 20);
}

/* ------------------------------------------------------------------ */
/*  Motors (L293D)                                                    */
/* ------------------------------------------------------------------ */
/* One wheel: speed -999..+999, negative = backwards */
static void motor_raw(int which_a, int speed)
{
    GPIO_PinState in_fwd = speed >= 0 ? GPIO_PIN_SET : GPIO_PIN_RESET;
    GPIO_PinState in_rev = speed >= 0 ? GPIO_PIN_RESET : GPIO_PIN_SET;
    int duty = speed < 0 ? -speed : speed;
    if (duty == 0) { in_fwd = GPIO_PIN_RESET; in_rev = GPIO_PIN_RESET; }

    if (which_a) {      /* motor A: IN1 = A2, IN2 = A1, EN = A3 (TIM2 CH4) */
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_2, in_fwd);
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_1, in_rev);
        __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_4, duty);
    } else {            /* motor B: IN3 = A4, IN4 = A5, EN = A0 (TIM2 CH1) */
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_4, in_fwd);
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, in_rev);
        __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, duty);
    }
}

/* Both wheels. Positive = forward. Limited to MAX_SPEED. */
static void drive(int left, int right)
{
    speed_l = clamp(left, -MAX_SPEED, MAX_SPEED);
    speed_r = clamp(right, -MAX_SPEED, MAX_SPEED);
    int l = speed_l * LEFT_TRIM / 100;     /* weaken the stronger wheel */
    int r = speed_r * RIGHT_TRIM / 100;
    if (MOTOR_LEFT_REVERSED)  l = -l;
    if (MOTOR_RIGHT_REVERSED) r = -r;
    motor_raw(MOTOR_A_IS_LEFT ? 1 : 0, l);
    motor_raw(MOTOR_A_IS_LEFT ? 0 : 1, r);
}

/* Short the motors through the driver: stops much faster than coasting */
static void brake(void)
{
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_1 | GPIO_PIN_2 | GPIO_PIN_4 | GPIO_PIN_5, GPIO_PIN_RESET);
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_4, PWM_MAX);
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, PWM_MAX);
    speed_l = speed_r = 0;
}

static void stop_motors(void) { drive(0, 0); }

/* ------------------------------------------------------------------ */
/*  Servo (smooth movement)                                           */
/* ------------------------------------------------------------------ */
static void servo_set(int us)
{
    servo_target = clamp(us, 500, 2500);
    if (!servo_on) {                       /* first use: start the signal */
        servo_now = servo_target;
        __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_4, servo_now);
        HAL_TIM_PWM_Start(&htim3, TIM_CHANNEL_4);
        servo_on = 1;
    }
}

static void servo_update(uint32_t now)
{
    if (!servo_on || now - servo_t < 10) return;
    servo_t = now;
    if (servo_now < servo_target) servo_now = clamp(servo_now + SERVO_STEP_US, 0, servo_target);
    else if (servo_now > servo_target) servo_now = clamp(servo_now - SERVO_STEP_US, servo_target, 3000);
    __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_4, servo_now);
}

/* ------------------------------------------------------------------ */
/*  Buttons (debounced, short and long press)                         */
/* ------------------------------------------------------------------ */
static void button_update(Button *b, uint32_t now)
{
    uint8_t raw = HAL_GPIO_ReadPin(b->port, b->pin) == GPIO_PIN_SET;  /* pressed = 3.3 V */
    if (raw != b->last_raw) { b->last_raw = raw; b->changed_at = now; }
    if (now - b->changed_at < 30 || raw == b->stable) {
        if (b->stable && !b->long_done && now - b->pressed_at >= LONG_PRESS_MS) {
            b->long_done = 1; b->long_event = 1;
        }
        return;
    }
    b->stable = raw;
    if (raw) { b->pressed_at = now; b->long_done = 0; }
    else if (!b->long_done) b->short_event = 1;
}

/* ------------------------------------------------------------------ */
/*  Line sensors                                                      */
/* ------------------------------------------------------------------ */
static uint8_t read_black_bits(void)
{
    uint8_t lvl = SENSOR_BLACK_LEVEL ? 1 : 0, b = 0;
    if ((HAL_GPIO_ReadPin(S0_PORT, S0_PIN) == GPIO_PIN_SET) == lvl) b |= 1;
    if ((HAL_GPIO_ReadPin(S1_PORT, S1_PIN) == GPIO_PIN_SET) == lvl) b |= 2;
    if ((HAL_GPIO_ReadPin(S2_PORT, S2_PIN) == GPIO_PIN_SET) == lvl) b |= 4;
    if ((HAL_GPIO_ReadPin(S3_PORT, S3_PIN) == GPIO_PIN_SET) == lvl) b |= 8;
    return b;
}

uint8_t Robot_LineCount(uint8_t bits)
{
    uint8_t n = 0;
    for (int i = 0; i < 4; i++) n += (bits >> i) & 1;
    return n;
}

/* Where is the line? -30 (far left) .. 0 (centre) .. +30 (far right).
 * Average position of the sensors that see it. None: keep the old value. */
int Robot_LineError(uint8_t bits, int last)
{
    static const int pos[4] = { -30, -10, 10, 30 };
    int sum = 0, n = 0;
    for (int i = 0; i < 4; i++) if (bits & (1 << i)) { sum += pos[i]; n++; }
    return n ? sum / n : last;
}

/* ------------------------------------------------------------------ */
/*  AUTO mode: line following state machine                           */
/* ------------------------------------------------------------------ */
static void auto_enter(AutoState s, uint32_t now) { astate = s; state_t0 = now; }

static void follow_pd(void)
{
    int d = error - last_error;
    int corr = (KP * error + KD * d) / 10;      /* error is x10, so divide back */
    drive(BASE_SPEED + corr, BASE_SPEED - corr);
}

static void start_junction_action(uint32_t now)
{
    RouteAction a = junction_index < ROUTE_LEN ? route[junction_index] : R_FOLLOW;
    junction_index++;
    switch (a) {
    case R_LEFT:  case R_RIGHT:
        turn_dir = (a == R_LEFT) ? -1 : 1;
        turn_left_line = 0;
        auto_enter(AS_TURN, now);
        break;
    case R_STRAIGHT:
        auto_enter(AS_CROSS, now);
        break;
    case R_FINISH:
        finish_armed = 1;
        auto_enter(AS_FOLLOW, now);
        break;
    default:
        auto_enter(AS_FOLLOW, now);
        break;
    }
}

static void auto_step(uint32_t now)
{
    uint8_t n = Robot_LineCount(line_bits);

    switch (astate) {
    case AS_IDLE: case AS_LOST: case AS_FINISHED:
        stop_motors();
        return;

    case AS_FOLLOW:
        if (n >= 3) {                           /* junction, or the background changed colour */
            auto_enter(AS_WIDE, now);
            drive(BASE_SPEED, BASE_SPEED);
            return;
        }
        if (n == 0) {                           /* no line under any sensor */
            if (!was_lost) { was_lost = 1; lost_t0 = now; }
            uint32_t t = now - lost_t0;
            if (finish_armed && t > GAP_MS) {   /* end of the line after the last junction */
                brake(); auto_enter(AS_FINISHED, now);
                debug_print("FINISH: stopped\r\n");
                return;
            }
            if (t < GAP_MS)                     /* dashed line: keep straight */
                drive(BASE_SPEED, BASE_SPEED);
            else if (t < GAP_MS + SEARCH_MS) {  /* turn towards where it was */
                if (last_side) drive(last_side * SEARCH_SPEED, -last_side * SEARCH_SPEED);
                else           drive(SEARCH_SPEED, SEARCH_SPEED);   /* never saw a side: go straight */
            }
            else {
                brake(); auto_enter(AS_LOST, now);
                debug_print("LOST: line not found, press START to try again\r\n");
            }
            return;
        }
        was_lost = 0;
        error = Robot_LineError(line_bits, error);
        if (error != 0) last_side = error < 0 ? -1 : 1;
        follow_pd();
        last_error = error;
        return;

    case AS_WIDE:
        drive(BASE_SPEED, BASE_SPEED);
        if (n >= 3) {
            if (now - state_t0 >= WIDE_TO_INVERT_MS) {   /* long wide area = colour swap */
                inverted ^= 1;
                debug_print(inverted ? "Background is BLACK now: following the WHITE line\r\n"
                                     : "Background is WHITE again: following the BLACK line\r\n");
                last_error = error = 0;
                auto_enter(AS_FOLLOW, now);
            }
            return;
        }
        start_junction_action(now);              /* short wide area = junction */
        return;

    case AS_CROSS:
        drive(BASE_SPEED, BASE_SPEED);
        if (now - state_t0 >= JUNCTION_PASS_MS) auto_enter(AS_FOLLOW, now);
        return;

    case AS_TURN:
        /* spin towards the branch: first leave the old line, then find the new one */
        drive(turn_dir * SEARCH_SPEED, -turn_dir * SEARCH_SPEED);
        if (!turn_left_line) {
            if ((line_bits & 0x6) == 0) turn_left_line = 1;      /* centre sensors off the line */
        } else if (line_bits & 0x6) {                            /* centre sensor found a line */
            last_error = error = 0;
            auto_enter(AS_FOLLOW, now);
        }
        if (now - state_t0 > TURN_MAX_MS) auto_enter(AS_FOLLOW, now);
        return;
    }
}

static void auto_start(uint32_t now)
{
    was_lost = 0;
    last_error = error = 0;
    servo_set(SERVO_AUTO_US);
    auto_enter(AS_FOLLOW, now);
    debug_print("AUTO: GO\r\n");
}

static void auto_reset_route(void)
{
    junction_index = 0; inverted = 0; finish_armed = 0;
    debug_print("AUTO: route reset to the Start Zone\r\n");
}

/* ------------------------------------------------------------------ */
/*  MANUAL mode: Bluetooth commands                                   */
/* ------------------------------------------------------------------ */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart3) {
        uint8_t next = (uint8_t)((bt_head + 1) % sizeof(bt_buf));
        if (next != bt_tail) { bt_buf[bt_head] = bt_byte; bt_head = next; }
        HAL_UART_Receive_IT(&huart3, &bt_byte, 1);
    }
}

void HAL_UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart3) HAL_UART_Receive_IT(&huart3, &bt_byte, 1);   /* recover after noise */
}

static int bt_read(void)
{
    if (bt_tail == bt_head) return -1;
    uint8_t c = bt_buf[bt_tail];
    bt_tail = (uint8_t)((bt_tail + 1) % sizeof(bt_buf));
    return c;
}

static void manual_step(uint32_t now)
{
    int c;
    while ((c = bt_read()) >= 0) {
        int s = manual_speed, t = MANUAL_TURN_SPEED;
        bt_last = now;
        switch (c) {
        case 'F': drive(s, s);           break;
        case 'B': drive(-s, -s);         break;
        case 'L': drive(-t, t);          break;   /* spin left on the spot  */
        case 'R': drive(t, -t);          break;   /* spin right on the spot */
        case 'G': drive(s / 3, s);       break;   /* forward-left           */
        case 'I': drive(s, s / 3);       break;   /* forward-right          */
        case 'H': drive(-s / 3, -s);     break;   /* back-left              */
        case 'J': drive(-s, -s / 3);     break;   /* back-right             */
        case 'S': stop_motors();         break;
        case 'W': case 'C': servo_set(SERVO_CLOSED_US); break;
        case 'w': case 'O': servo_set(SERVO_OPEN_US);   break;
        case 'q': manual_speed = MAX_SPEED; break;
        default:
            if (c >= '0' && c <= '9') manual_speed = 300 + (c - '0') * (MAX_SPEED - 300) / 9;
            break;
        }
    }
    if (BT_TIMEOUT_MS && now - bt_last > BT_TIMEOUT_MS) stop_motors();
}

/* ------------------------------------------------------------------ */
/*  TEST modes                                                        */
/* ------------------------------------------------------------------ */
static void motor_test_step(uint32_t now)
{
    static int last_phase = -1;
    if (!mt_running) { stop_motors(); last_phase = -1; return; }
    uint32_t t = now - mt_t0;
    int phase = (int)(t / 1000);
    if (phase != last_phase) {
        static const char *msg[] = {
            "MOTOR TEST 1/4: LEFT wheel forward\r\n", "MOTOR TEST 2/4: RIGHT wheel forward\r\n",
            "MOTOR TEST 3/4: BOTH forward\r\n",       "MOTOR TEST 4/4: spin RIGHT on the spot\r\n",
            "MOTOR TEST done\r\n" };
        if (phase <= 4) debug_print(msg[phase]);
        last_phase = phase;
    }
    switch (phase) {
    case 0: drive(500, 0);    break;
    case 1: drive(0, 500);    break;
    case 2: drive(500, 500);  break;
    case 3: drive(450, -450); break;
    default: stop_motors(); mt_running = 0; break;
    }
}

/* ------------------------------------------------------------------ */
/*  LEDs and debug                                                    */
/* ------------------------------------------------------------------ */
static void leds(uint8_t a, uint8_t b, uint8_t c)
{
    HAL_GPIO_WritePin(LED1_PORT, LED1_PIN, a ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(LED2_PORT, LED2_PIN, b ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(LED3_PORT, LED3_PIN, c ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

static void update_leds(uint32_t now)
{
    uint8_t blink = (now / 250) & 1;
    if (mode == MODE_AUTO) {
        switch (astate) {
        case AS_IDLE:     leds(1, 0, 0); break;                    /* ready              */
        case AS_LOST:     leds(blink, blink, blink); break;        /* all blinking       */
        case AS_FINISHED: leds(1, 1, 1); break;                    /* all on             */
        default:          leds(blink, 0, inverted); break;         /* running; LED3 = white-line mode */
        }
    } else if (mode == MODE_MANUAL)      leds(0, 1, 0);
    else if (mode == MODE_SENSOR_TEST)   leds(0, 0, 1);
    else                                 leds(1, 0, 1);
}

static void print_status(uint32_t now)
{
    if (!DEBUG_PRINT_MS || now - print_t < DEBUG_PRINT_MS) return;
    print_t = now;
    char s[96];
    snprintf(s, sizeof s, "%-6s %-6s black=%d%d%d%d inv=%d err=%3d L=%4d R=%4d junc=%d btn=%d%d\r\n",
             MODE_NAME[mode], mode == MODE_AUTO ? STATE_NAME[astate] : "-",
             black_bits & 1, (black_bits >> 1) & 1, (black_bits >> 2) & 1, (black_bits >> 3) & 1,
             inverted, error, speed_l, speed_r, junction_index,
             HAL_GPIO_ReadPin(BTN_START_PORT, BTN_START_PIN),
             HAL_GPIO_ReadPin(BTN_MODE_PORT, BTN_MODE_PIN));
    debug_print(s);
}

/* ------------------------------------------------------------------ */
/*  Public functions                                                  */
/* ------------------------------------------------------------------ */
void Robot_Init(void)
{
    /* SAFE START: motors off BEFORE the PWM signal is switched on.
       Direction pins LOW + duty 0 = no current to the motors.          */
    stop_motors();
    leds(0, 0, 0);
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_4);
    /* The servo signal is NOT started here: the servo stays limp and
       silent until AUTO starts or you send a gate command.             */
    HAL_UART_Receive_IT(&huart3, &bt_byte, 1);
    leds(1, 1, 1); HAL_Delay(300); leds(0, 0, 0);       /* "I'm alive" flash */
    debug_print("\r\nAutocar ready v2. MODE button = change mode, START = go/stop, hold START = reset route\r\n");
    loop_t = HAL_GetTick();
}

void Robot_Loop(void)
{
    uint32_t now = HAL_GetTick();
    if (now - loop_t < LOOP_MS) return;
    loop_t = now;

    /* 1. buttons */
    button_update(&btn_start, now);
    button_update(&btn_mode, now);
    uint8_t running = (mode == MODE_AUTO && astate != AS_IDLE && astate != AS_LOST && astate != AS_FINISHED)
                      || (mode == MODE_MOTOR_TEST && mt_running);

    if (btn_mode.short_event) {
        btn_mode.short_event = 0;
        if (!running) {
            stop_motors();
            mode = (Mode)((mode + 1) % MODE_COUNT);
            char s[40]; snprintf(s, sizeof s, "MODE -> %s\r\n", MODE_NAME[mode]); debug_print(s);
        }
    }
    btn_mode.long_event = 0;

    if (btn_start.short_event) {
        btn_start.short_event = 0;
        if (mode == MODE_AUTO) {
            if (running) { brake(); auto_enter(AS_IDLE, now); debug_print("AUTO: stopped\r\n"); }
            else auto_start(now);
        } else if (mode == MODE_MOTOR_TEST) {
            mt_running = !mt_running; mt_t0 = now;
        } else if (mode == MODE_MANUAL) {
            stop_motors();
        }
    }
    if (btn_start.long_event) {
        btn_start.long_event = 0;
        if (mode == MODE_AUTO && !running) auto_reset_route();
    }

    /* 2. sensors */
    black_bits = read_black_bits();
    line_bits = inverted ? (uint8_t)(~black_bits & 0x0F) : black_bits;

    /* 3. mode */
    switch (mode) {
    case MODE_AUTO:        auto_step(now);       break;
    case MODE_MANUAL:      manual_step(now);     break;
    case MODE_MOTOR_TEST:  motor_test_step(now); break;
    default:               stop_motors();        break;
    }

    /* 4-5. servo, LEDs, debug */
    servo_update(now);
    update_leds(now);
    print_status(now);
}
